mapper.select:
select ca.accntcategory as categoryType, round(sum(vd.dr_func-vd.cr_func),2) as categoryAmount from voucher v, voucherdetails vd, coaa ca where v.portfolionum in
#{item}
and v.ledgerdate<=#{calDate} and v.vouchernum=vd.vouchernum and vd.chartNum=ca.chartnumber and vd.accountNum=ca.accntnum and ca.acctisleaf=1 group by ca.accntcategory
